std::random_device rd;
std::mt19937 gen(rd());
std::uniform_real_distribution<double> dis(0.0, 1.0);

int oddCount = 0;
int evenCount = 0;

for (int i = 0; i < numberOfChecks; ++i) {
    // Generate a random direction
    Vec3d dir;
    do {
        dir = Vec3d(
            dis(gen) * 2.0 - 1.0,
            dis(gen) * 2.0 - 1.0,
            dis(gen) * 2.0 - 1.0
        );
    } while (dir.squaredNorm() < CGAL::NORM_SQUARED_TOLERANCE);

    dir.normalize();

    // Create ray from point in random direction
    CGALRay ray(p, p + dir * 1e6); // Large distance to ensure ray exits mesh

    // Count intersections
    int count = tree.numberIntersectedPrimitives(ray);

    // Odd number of intersections means point is inside
    if (count % 2 == 1) {
        oddCount++;
    } else {
        evenCount++;
    }
}

// If more than half of the rays have odd intersections, consider point inside
return oddCount > evenCount;

